function obtenerVocales(palabra) {
  let vocales = [];
  let id = palabra + "_" + Date.now();
  for (let i = 0; i < palabra.length; i++) {
    let letra = palabra[i];
    if (letra === 'a' || letra === 'e' || letra === 'i' || letra === 'o' || letra === 'u') {
      vocales.push(letra);
    }
  }
  return {
    id: id,
    vocales: vocales
  }
}

